sys_script_client.script:
var feeStructureValidated = false;

function showError(fieldName, message) {
    g_form.addErrorMessage(message);
    g_form.getControl(fieldName).focus();
}

function onSubmit() {

    // Second pass: validation already succeeded, let the form submit
    if (feeStructureValidated) {
        feeStructureValidated = false;
        return true;
    }

    var amount = parseFloat(g_form.getValue('amount').replace(/[^0-9.\-]/g, ''));
    var semNo = parseInt(g_form.getValue('sem_no'), 10);
    var effectiveFrom = g_form.getValue('effective_from');
    var effectiveTo = g_form.getValue('effective_to');

    // 1. Amount must be positive
    if (isNaN(amount) || amount <= 0) {
        showError('amount', 'Amount must be greater than zero.');
        return false;
    }

    // 2. Semester Number must be positive
    if (isNaN(semNo) || semNo <= 0) {
        showError('sem_no', 'Semester Number must be greater than zero.');
        return false;
    }

    // 3. Effective From must be earlier than Effective To (only when both are filled)
    if (effectiveFrom && effectiveTo) {
        var fromTime = getDateFromFormat(effectiveFrom, g_user_date_format);
        var toTime = getDateFromFormat(effectiveTo, g_user_date_format);

        if (fromTime >= toTime) {
            showError('effective_to', 'Effective From must be earlier than Effective To.');
            return false;
        }
    }

    // 4. Semester Number must not exceed Program duration (async lookup)
    g_form.getReference('program', function(programRecord) {

        var duration = parseInt(programRecord.duration_sem, 10);

        if (isNaN(duration) || duration <= 0) {
            showError('program', 'Selected Program has an invalid Semester Duration.');
            return;
        }

        if (semNo > duration) {
            showError('sem_no', 'Semester Number cannot exceed the Program Duration (' + duration + ' Semesters).');
            return;
        }

        // All validations passed, submit again
        feeStructureValidated = true;
        g_form.submit();
    });

    // Block the first submit while the Program lookup runs
    return false;
}
